*/


/**
 * @method
 * @name comite_rslt_attach
 * @description desc
 * @param {string} bzProcsNo desc
 * @param {string} comiteDd desc
 * @param {string} seq desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.comite_rslt_attach = function(bzProcsNo, comiteDd, seq) {
    $.ajax({
        type: "POST",
        url: "/elasticNoti.do",
        data: {
            method: "indexingElasitcSearch",
            P_bzProcsNo: bzProcsNo,
            P_comiteDd: comiteDd,
            P_seq: seq,
            url: "/api/elastic/indexing/tbld_comite_rslt_attach/kafka",
            type: "POST"
        },
        async: true
    });
};
